-- Unity version (0.5.0): world layout and server-side market orders.
--  * cfg.world lists what exists in the Unity world: MVP crops, the animals in the pens (one entry per
--    animal, in id order per type), and the products market orders may ask for.
--  * Market orders live in farms.orders and are generated by the server, so a client cannot invent a
--    rich order. Replacing an order puts its slot on a 2-minute cooldown.
--  * hf_action, hf_init_player and hf_get_state are wrapped; the old functions become *_core and are
--    no longer callable by players.

update public.game_config set data = data || jsonb_build_object('world', jsonb_build_object(
  'crops', jsonb_build_array('wheat', 'carrot', 'tomato', 'corn', 'pumpkin'),
  'animals', jsonb_build_array('cow', 'cow', 'sheep', 'sheep', 'chicken', 'chicken', 'chicken', 'chicken'),
  'animal_products', jsonb_build_array('egg', 'milk', 'wool'),
  'recipes', jsonb_build_array('flour', 'bread', 'pumpkin_pie', 'cheese'),
  'order_slots', 3, 'order_replace_seconds', 120)), updated_at = now() where id = 1;

alter table public.farms add column if not exists orders jsonb not null default '[]'::jsonb;

-- ------------------------------------------------------------------ helpers

create or replace function public.hf_new_order(cfg jsonb, lvl int, workshops jsonb, avail double precision) returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare pool text[] := '{}'; k text; r text; ws text; items jsonb := '{}'::jsonb; n int; i int; pick text; q int; value int := 0; coins int;
begin
  for k in select jsonb_array_elements_text(cfg->'world'->'crops') loop
    if coalesce((cfg->'crops'->k->>'unlock_level')::int, 1) <= lvl then pool := pool || k; end if;
  end loop;
  for k in select jsonb_array_elements_text(cfg->'world'->'animal_products') loop pool := pool || k; end loop;
  for ws in select jsonb_object_keys(coalesce(workshops, '{}'::jsonb)) loop
    for r in select jsonb_array_elements_text(cfg->'workshops'->ws->'recipes') loop
      if cfg->'world'->'recipes' ? r and not (r = any(pool)) then pool := pool || r; end if;
    end loop;
  end loop;
  n := case when array_length(pool, 1) > 1 and random() < 0.5 then 2 else 1 end;
  for i in 1 .. n loop
    pick := pool[1 + floor(random() * array_length(pool, 1))::int];
    pool := array_remove(pool, pick);
    q := case when cfg->'world'->'crops' ? pick then 3 + floor(random() * 6)::int
              when cfg->'world'->'recipes' ? pick then 1 + floor(random() * 2)::int
              else 1 + floor(random() * 3)::int end;
    items := items || jsonb_build_object(pick, q);
    value := value + coalesce((cfg->'items'->pick->>'sell_price')::int, 1) * q;
  end loop;
  coins := ceil(value * 1.5)::int + 5;   -- orders pay half again what the market stall pays
  return jsonb_build_object('items', items, 'coins', coins, 'xp', greatest(2, coins / 8), 'available_at', avail);
end $$;

-- Tops up the order slots and brings the animals in line with the Unity world. Called with the farm locked.
create or replace function public.hf_prepare_farm(p uuid, cfg jsonb, t double precision) returns void
language plpgsql security definer set search_path = public as $$
declare f public.farms%rowtype; lvl int; v_orders jsonb; layout jsonb := cfg->'world'->'animals'; v_animals jsonb := '[]'::jsonb; k text;
begin
  select * into f from public.farms where player_id = p for update;
  if not found or cfg->'world' is null then return; end if;
  select level into lvl from public.profiles where id = p;
  if (select coalesce(jsonb_agg(a->>'type'), '[]'::jsonb) from jsonb_array_elements(f.animals) a) <> layout then
    for k in select jsonb_array_elements_text(layout) loop
      v_animals := v_animals || jsonb_build_array(jsonb_build_object('type', k, 'status', 'hungry', 'started_at', 0,
        'hungry_since', t, 'happiness', coalesce((cfg->'animal_care'->>'start_happiness')::int, 70)));
    end loop;
    update public.farms set animals = v_animals where player_id = p;
  end if;
  v_orders := f.orders;
  while jsonb_array_length(v_orders) < coalesce((cfg->'world'->>'order_slots')::int, 3) loop
    v_orders := v_orders || jsonb_build_array(public.hf_new_order(cfg, lvl, f.workshops, t));
  end loop;
  if v_orders <> f.orders then update public.farms set orders = v_orders where player_id = p; end if;
end $$;

-- ------------------------------------------------------------------ wrap the public RPCs

alter function public.hf_state(uuid) rename to hf_state_core;
create or replace function public.hf_state(p uuid) returns jsonb
language sql stable security definer set search_path = public as $$
  select public.hf_state_core(p) || jsonb_build_object('orders', (select orders from public.farms where player_id = p)) $$;

alter function public.hf_init_player(text) rename to hf_init_player_core;
create or replace function public.hf_init_player(p_display_name text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
begin
  perform public.hf_init_player_core(p_display_name);
  perform public.hf_prepare_farm(auth.uid(), public.hf_cfg(), public.hf_now());
  return public.hf_state(auth.uid());
end $$;

create or replace function public.hf_get_state() returns jsonb
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  perform public.hf_prepare_farm(auth.uid(), public.hf_cfg(), public.hf_now());
  return public.hf_state(auth.uid());
end $$;

alter function public.hf_action(text, jsonb, uuid) rename to hf_action_core;
create or replace function public.hf_action(p_action text, p_args jsonb, p_key uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); cfg jsonb := public.hf_cfg(); t double precision := public.hf_now();
        prev jsonb; res jsonb; f public.farms%rowtype; lvl int; idx int; o jsonb; k text; levels int;
begin
  if uid is null then raise exception 'not authenticated'; end if;
  if p_action not in ('deliver_order', 'replace_order') then
    res := public.hf_action_core(p_action, p_args, p_key);
    perform public.hf_prepare_farm(uid, cfg, t);   -- a level-up or new workshop widens the order pool next time
    return res || jsonb_build_object('state', public.hf_state(uid));
  end if;
  if p_key is null then return public.hf_err('invalid'); end if;
  perform 1 from public.wallets where player_id = uid for update;
  if not found then return public.hf_err('no_player'); end if;
  select result into prev from public.processed_actions where player_id = uid and idempotency_key = p_key;
  if found then return prev || jsonb_build_object('replayed', true, 'state', public.hf_state(uid)); end if;
  perform public.hf_prepare_farm(uid, cfg, t);
  select * into f from public.farms where player_id = uid for update;
  select level into lvl from public.profiles where id = uid;
  idx := (coalesce(p_args, '{}'::jsonb)->>'idx')::int;
  if idx is null or idx < 0 or idx >= jsonb_array_length(f.orders) then res := public.hf_err('invalid');
  else
    o := f.orders->idx;
    if (o->>'available_at')::double precision > t then res := public.hf_err('not_ready');
    elsif p_action = 'replace_order' then
      update public.farms set orders = jsonb_set(orders, array[idx::text],
        public.hf_new_order(cfg, lvl, f.workshops, t + coalesce((cfg->'world'->>'order_replace_seconds')::int, 120)))
       where player_id = uid;
      res := public.hf_ok();
    else
      for k in select jsonb_object_keys(o->'items') loop
        if public.hf_inv_count(uid, k) < (o->'items'->>k)::int then res := public.hf_err('missing_items'); end if;
      end loop;
      if res is null then
        for k in select jsonb_object_keys(o->'items') loop
          perform public.hf_inv_remove(uid, k, (o->'items'->>k)::int, 'market_order');
          perform public.hf_track(uid, cfg, 'sell', k, (o->'items'->>k)::int, t);
        end loop;
        perform public.hf_money(uid, 'coins', (o->>'coins')::int, 'market_order', idx::text);
        levels := public.hf_add_xp(uid, cfg, (o->>'xp')::int);
        select level into lvl from public.profiles where id = uid;
        update public.farms set orders = jsonb_set(orders, array[idx::text], public.hf_new_order(cfg, lvl, f.workshops, t))
         where player_id = uid;
        res := public.hf_ok(jsonb_build_object('coins', (o->>'coins')::int, 'xp', (o->>'xp')::int, 'levels', levels));
      end if;
    end if;
  end if;
  insert into public.processed_actions (player_id, idempotency_key, action, result) values (uid, p_key, p_action, res);
  return res || jsonb_build_object('state', public.hf_state(uid));
end $$;

-- ------------------------------------------------------------------ permissions
revoke execute on function public.hf_state_core(uuid), public.hf_init_player_core(text), public.hf_action_core(text, jsonb, uuid),
  public.hf_new_order(jsonb, int, jsonb, double precision), public.hf_prepare_farm(uuid, jsonb, double precision),
  public.hf_state(uuid) from public, anon, authenticated;
revoke execute on function public.hf_init_player(text), public.hf_get_state(), public.hf_action(text, jsonb, uuid) from public, anon;
grant execute on function public.hf_init_player(text), public.hf_get_state(), public.hf_action(text, jsonb, uuid) to authenticated;
